import gsap from "gsap"
import { useGSAP } from "@gsap/react"
import Skeleton from 'react-loading-skeleton'
import 'react-loading-skeleton/dist/skeleton.css'

const BlurHome = () => {

    useGSAP( () => {
        gsap.to(".blurs", {
            x:990,
            duration: 1,
            repeat: 10,
        })
    },[])

    return(

        // <>
        //     <Skeleton height={460} width={`100%`} baseColor="#faf7f7" highlightColor="#aba9a9" />
        // </>

        <div className="Mainblurs" >
            <div className="blurs" ></div>
        </div>
    )
}

export default BlurHome
